  for (const field of ['python','policy','ledger']) abs(x[field], 'OPERATOR_PATH_NOT_ABSOLUTE');
  for (const field of ['actor','service'])
    need(typeof x[field] === 'string' && /^[A-Za-z0-9._:-]{1,160}$/.test(x[field]),
