const SCHEMA='stellar-forge.sf88.unpaid-continuation.v1';
const WORKER=fileURLToPath(new URL('./dataset-unpaid.py',import.meta.url));
const HASH=/^[a-f0-9]{64}$/;
const F=constants.O_NOFOLLOW??0;
