      failure = error; pinned = { address, family };
    });
    if (failure) throw failure;
    need(pinned?.address && [4, 6].includes(pinned.family), 'CATALOG_PIN_UNAVAILABLE');
    const target = new URL(`https://${options.hostname}`);
